-- ===================== Sequence-assignment trigger (hand-authored) =====================
-- PG analog of SQL Server's AFTER INSERT trgConversationDetail_AssignSequence.
-- BEFORE INSERT FOR EACH ROW + a per-conversation transaction-scoped advisory lock is the
-- UPDLOCK/HOLDLOCK analog: concurrent transactions inserting into the same conversation
-- serialize on the lock, held until commit, so the loser's MAX(...) (fresh READ COMMITTED
-- snapshot taken after the lock is granted) sees the winner's committed rows.
-- CAVEAT (documented): under SERIALIZABLE/REPEATABLE READ the blocked transaction's
-- snapshot predates the winner's commit → duplicates possible; MJ runs READ COMMITTED.
CREATE OR REPLACE FUNCTION __mj."trgConversationDetail_AssignSequence_func"()
RETURNS TRIGGER AS $$
BEGIN
    -- Serialize per conversation. Two-int form namespaces our lock class (0x4D4A5345 =
    -- 'MJSE') away from any future advisory-lock users; hashtext collisions across
    -- conversations only coarsen lock granularity (extra serialization), never correctness.
    PERFORM pg_advisory_xact_lock(1296126789, hashtext(NEW."ConversationID"::text));

    -- Unconditional assignment, mirroring the SS trigger (which overwrites any
    -- caller-supplied value). Within a multi-row INSERT, PostgreSQL's command-visibility
    -- rules mean this MAX sees earlier rows of the SAME statement, whose BEFORE triggers
    -- already assigned their Sequence — so batch inserts get distinct ascending values.
    SELECT COALESCE(MAX("Sequence"), 0) + 1
      INTO NEW."Sequence"
      FROM __mj."ConversationDetail"
     WHERE "ConversationID" = NEW."ConversationID";

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

