CREATE TRIGGER "trgConversationDetail_AssignSequence"
    BEFORE INSERT ON __mj."ConversationDetail"
    FOR EACH ROW
    EXECUTE FUNCTION __mj."trgConversationDetail_AssignSequence_func"();

