------------------------------------------------------------
CREATE OR REPLACE FUNCTION __mj."fn_conversation_last_conversation_id_get_root_id"(
    p_record_id UUID,
    p_parent_id UUID
) RETURNS UUID AS $$
    WITH RECURSIVE cte_root_parent AS (
        -- Anchor: Start from p_parent_id if not null, otherwise start from p_record_id
        SELECT
            "ID",
            "LastConversationID",
            "ID" AS root_parent_id,
            0 AS depth
        FROM
            __mj."Conversation"
        WHERE
            "ID" = COALESCE(p_parent_id, p_record_id)

        UNION ALL

        -- Recursive: Keep going up the hierarchy
        SELECT
            c."ID",
            c."LastConversationID",
            c."ID" AS root_parent_id,
            p.depth + 1 AS depth
        FROM
            __mj."Conversation" c
        INNER JOIN
            cte_root_parent p ON c."ID" = p."LastConversationID"
        WHERE
            p.depth < 100  -- Prevent infinite loops
    )
    SELECT root_parent_id
    FROM cte_root_parent
    WHERE "LastConversationID" IS NULL
    ORDER BY root_parent_id
    LIMIT 1;
$$ LANGUAGE sql STABLE;


